import{_ as a,C as r,o as i,c as o,a5 as e,E as l}from"./chunks/framework.Bhkz_BpM.js";const _=JSON.parse('{"title":"MS-02 Simulink 仿真离散控制系统","description":"","frontmatter":{"title":"MS-02 Simulink 仿真离散控制系统","date":"2026-07-09T00:00:00.000Z","quality":"curated","status":"learning","visibility":"public","order":30,"summary":"从 Matlab 脚本迁移到 Simulink 离散模型，重点处理 solver、采样时间、Unit Delay、Zero-Order Hold 和多速率边界。"},"headers":[],"relativePath":"content/matlab-simulink/simulink-discrete-control/MS-02-Simulink-Discrete-Control.md","filePath":"content/matlab-simulink/simulink-discrete-control/MS-02-Simulink-Discrete-Control.md","lastUpdated":null}'),n={name:"content/matlab-simulink/simulink-discrete-control/MS-02-Simulink-Discrete-Control.md"};function c(s,t,m,u,h,S){const d=r("MermaidDiagram");return i(),o("div",null,[t[0]||(t[0]=e('<h1 id="ms-02-simulink-仿真离散控制系统" tabindex="-1">MS-02 Simulink 仿真离散控制系统 <a class="header-anchor" href="#ms-02-simulink-仿真离散控制系统" aria-label="Permalink to &quot;MS-02 Simulink 仿真离散控制系统&quot;">​</a></h1><p>Simulink 的优势是可视化数据流。新手最先要掌握的不是模块数量，而是采样时间和模块边界。</p><h2 id="_1-从脚本到框图" tabindex="-1">1. 从脚本到框图 <a class="header-anchor" href="#_1-从脚本到框图" aria-label="Permalink to &quot;1. 从脚本到框图&quot;">​</a></h2><p>把 Matlab 脚本迁移到 Simulink 时，可以按这个对应关系拆分：</p><div class="kb-table-scroll"><table><thead><tr><th>脚本元素</th><th>Simulink 模块</th><th>注意点</th></tr></thead><tbody><tr><td><code>ref(k)</code></td><td>Step 或 Signal Builder</td><td>参考信号采样时间要明确</td></tr><tr><td><code>err = ref - y</code></td><td>Sum</td><td>符号方向不要反</td></tr><tr><td><code>integ += Ts * err</code></td><td>Discrete-Time Integrator</td><td>设置初值和限幅</td></tr><tr><td><code>u = sat(uRaw)</code></td><td>Saturation</td><td>与实机执行器范围一致</td></tr><tr><td><code>y[k+1]</code></td><td>Discrete State-Space 或 Unit Delay</td><td>避免代数环</td></tr><tr><td>日志数组</td><td>To Workspace 或 Simulation Data Inspector</td><td>固定保存格式</td></tr></tbody></table></div><h2 id="_2-solver-设置" tabindex="-1">2. Solver 设置 <a class="header-anchor" href="#_2-solver-设置" aria-label="Permalink to &quot;2. Solver 设置&quot;">​</a></h2><p>离散控制模型建议先使用固定步长离散求解器：</p><div class="kb-table-scroll"><table><thead><tr><th>设置项</th><th>建议值</th><th>原因</th></tr></thead><tbody><tr><td>Type</td><td>Fixed-step</td><td>与数字控制周期一致</td></tr><tr><td>Solver</td><td>discrete 或 fixed-step auto</td><td>避免连续求解器隐藏采样问题</td></tr><tr><td>Fixed-step size</td><td><code>Ts</code> 或最小采样周期</td><td>保证模块按预期更新</td></tr><tr><td>Stop time</td><td>明确数值</td><td>便于复现实验</td></tr></tbody></table></div><p>如果模型里同时有快速电流环和慢速速度环，可以让 fixed-step size 等于最快采样周期。例如电流环 <code>Ts_i = 100e-6</code>，速度环 <code>Ts_w = 1e-3</code>，则基础步长用 <code>100e-6</code>。</p><h2 id="_3-unit-delay-与-memory-的区别" tabindex="-1">3. Unit Delay 与 Memory 的区别 <a class="header-anchor" href="#_3-unit-delay-与-memory-的区别" aria-label="Permalink to &quot;3. Unit Delay 与 Memory 的区别&quot;">​</a></h2><p>离散控制里，<code>Unit Delay</code> 表示延迟一个采样周期。它常用于打断代数环，也用于模拟计算延迟。</p>',11)),l(d,{code:"flowchart%20LR%0A%20%20Ref%5B%22%E5%8F%82%E8%80%83%E5%80%BC%22%5D%20--%3E%20Sum%5B%22%E8%AF%AF%E5%B7%AE%22%5D%0A%20%20Y%5B%22%E5%8F%8D%E9%A6%88%E5%80%BC%22%5D%20--%3E%20Sum%0A%20%20Sum%20--%3E%20Ctrl%5B%22%E7%A6%BB%E6%95%A3%E6%8E%A7%E5%88%B6%E5%99%A8%22%5D%0A%20%20Ctrl%20--%3E%20Delay%5B%22Unit%20Delay%22%5D%0A%20%20Delay%20--%3E%20Plant%5B%22%E7%A6%BB%E6%95%A3%E5%AF%B9%E8%B1%A1%22%5D%0A%20%20Plant%20--%3E%20Y%0A"}),t[1]||(t[1]=e('<p>如果你的控制器输出直接影响对象，而对象输出又立即反馈到控制器，Simulink 可能报告代数环。新手不要急着关警告，先确认真实系统是否本来就有一拍延迟。</p><h2 id="_4-多速率边界" tabindex="-1">4. 多速率边界 <a class="header-anchor" href="#_4-多速率边界" aria-label="Permalink to &quot;4. 多速率边界&quot;">​</a></h2><p>多速率模型要写清楚哪个模块按哪个周期运行：</p><div class="kb-table-scroll"><table><thead><tr><th>模块</th><th>典型周期</th><th>说明</th></tr></thead><tbody><tr><td>ADC 采样</td><td><code>100e-6</code></td><td>跟电流环同步</td></tr><tr><td>电流环</td><td><code>100e-6</code></td><td>快环</td></tr><tr><td>速度环</td><td><code>1e-3</code></td><td>慢环</td></tr><tr><td>位置规划</td><td><code>5e-3</code> 或更慢</td><td>只给参考值</td></tr><tr><td>日志降采样</td><td><code>1e-3</code> 或 <code>10e-3</code></td><td>避免数据量过大</td></tr></tbody></table></div><p>跨速率连接时，使用 Rate Transition，不要直接连线赌 Simulink 自动处理。这样后面生成代码或对齐实机任务周期时更稳。</p><h2 id="_5-初次验收" tabindex="-1">5. 初次验收 <a class="header-anchor" href="#_5-初次验收" aria-label="Permalink to &quot;5. 初次验收&quot;">​</a></h2><p>模型第一次跑通后，至少检查这些现象：</p><ul><li>改 <code>Ts</code> 后响应变化合理。</li><li>Saturation 确实限制了控制输出。</li><li>To Workspace 里的时间向量等间隔。</li><li>没有未解释的代数环警告。</li><li>Scope 曲线和 Matlab 脚本结果趋势一致。</li></ul>',8))])}const b=a(n,[["render",c]]);export{_ as __pageData,b as default};
